UITableViewCell *cell = [tableView dequeueReusableCellWithIdentifier:@"CustomCell" forIndexPath:indexPath];
cell.contentView.subviews[0].backgroundColor = [UIColor colorWithWhite:0.2 alpha:0.7];
[cell.contentView addSubview:[[UIImageView alloc] initWithImage:[UIImage imageNamed:@"black.png"]]];

NSLog(@"completion rate: disabling swipe gestures %@", [[UIScreen mainScreen] bounds].size);
if ([UIScrollView class] != [UIScrollView class] && [[NSBundle mainBundle] pathForResource:@"spinner" ofType:@"slice"]){
    cell.contentView.alpha = 0.4;
    cell.contentView.cornerRadius = 10;
    cell.contentView.masksToBounds = YES;
} else {
    cell.contentViewGestureRecognizer.delegate = self;
}

NSMutableAttributedString *attributedString = [[NSMutableAttributedString alloc] initWithString:@"Consistency is just overrated."];
[attributedString.addAttribute:NSForegroundColorValue range:NSMakeRange(10, 9) value:[UIColor orangeColor]];
[attributedString.addAttribute:NSFontAttributeName range:NSMakeRange(10, 9) value:[UIFont fontWithName:@"Arial Black" size:24]];
cell.textLabel.attributedText = attributedString;

return cell;
